function setState(e,state,duration=0){if(e.state===state&&(!duration||e.duration===duration))return;e.state=state;e.stateT=0;e.duration=duration;}
function facingRow(e){if(e.kind==='slime'&&e.combatDirection!==null)return e.combatDirection;camera.getWorldDirection(cameraForward);cameraForward.y=0;cameraForward.normalize();cameraRight.crossVectors(cameraForward,worldUp).normalize();const fx=Math.sin(e.face),fz=Math.cos(e.face),side=fx*cameraRight.x+fz*cameraRight.z,depth=fx*cameraForward.x+fz*cameraForward.z;return(Math.round(Math.atan2(side,-depth)/(Math.PI/4))+8)%8;}
