function updateCamera(){const cp=Math.cos(pitch);camera.position.set(player.x+Math.sin(yaw)*cp*distance,1.15+Math.sin(pitch)*distance,player.z+Math.cos(yaw)*cp*distance);camera.lookAt(player.x,1.05,player.z);}
function movePlayer(dx,dz,dt){if(!['idle','move'].includes(player.state))return;const speed=5.2;player.vx+=(dx*speed-player.vx)*Math.min(1,dt*9);player.vz+=(dz*speed-player.vz)*Math.min(1,dt*9);player.face=Math.atan2(dx,dz);setState(player,'move');}
