function updatePlayer(dt){player.attackCd=Math.max(0,player.attackCd-dt);player.invuln=Math.max(0,player.invuln-dt);player.energy=Math.min(100,player.energy+18*dt);if(player.combatTarget&&(player.combatTarget.dead||player.combatTarget.hp<=0)){player.combatTarget=null;player.combatDirection=null;player.combatMirror=false;player.queuedAttack=false;}const c=player.combatTarget;if(c){let dx=c.x-player.x,dz=c.z-player.z,d=Math.hypot(dx,dz)||1;player.face=Math.atan2(dx,dz);combatRing.visible=true;combatRing.position.set(c.x,.04,c.z);if(['idle','move'].includes(player.state)){if(d>2.18)movePlayer(dx/d,dz/d,dt);else if(d<1.88)movePlayer(-dx/d,-dz/d,dt);else{player.vx=player.vz=0;if(player.state==='move')setState(player,'idle');if(player.queuedAttack)performAttack(c);}}else{player.vx=player.vz=0;if(d<1.88){player.x=c.x-dx/d*2.02;player.z=c.z-dz/d*2.02;}}}else{combatRing.visible=false;let ix=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),iz=(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0);if(ix||iz){camera.getWorldDirection(cameraForward);cameraForward.y=0;cameraForward.normalize();cameraRight.crossVectors(cameraForward,worldUp).normalize();const dir=new THREE.Vector3().addScaledVector(cameraRight,ix).addScaledVector(cameraForward,-iz).normalize();movePlayer(dir.x,dir.z,dt);player.moveTarget=null;marker.visible=false;}else if(player.moveTarget&&['idle','move'].includes(player.state)){const dx=player.moveTarget.x-player.x,dz=player.moveTarget.z-player.z,d=Math.hypot(dx,dz);if(d>.2)movePlayer(dx/d,dz/d,dt);else{player.moveTarget=null;marker.visible=false;stopPlayer(dt);}}else stopPlayer(dt);}player.x=THREE.MathUtils.clamp(player.x+player.vx*dt,-28,28);player.z=THREE.MathUtils.clamp(player.z+player.vz*dt,-28,28);advance(player,dt);syncSprite(player);}
function advance(e,dt){e.stateT+=dt;if(e.duration&&e.stateT>=e.duration){if(e.state==='death'){e.dead=true;e.sprite.visible=e.shadow.visible=false;if(e!==player&&!e.respawning){e.respawning=true;if(target===e)target=null;setTimeout(()=>respawnEnemy(e),4000);}return;}e.duration=0;setState(e,'idle');}}
function respawnEnemy(e){e.x=e.spawnX+(Math.random()-.5)*2;e.z=e.spawnZ+(Math.random()-.5)*2;e.hp=e.maxHp;e.vx=e.vz=0;e.dead=false;e.respawning=false;e.aggro=false;e.attackCd=1;e.duration=0;e.combatDirection=null;setState(e,'idle');syncSprite(e);toast(`${e.name.toUpperCase()} IST ZURÜCK`,'#baff91');}
function updateEnemy(e,dt){if(e.dead)return;advance(e,dt);e.attackCd-=dt;if(['idle','move'].includes(e.state)&&e.aggro){const dx=player.x-e.x,dz=player.z-e.z,d=Math.hypot(dx,dz)||1;e.face=Math.atan2(dx,dz);if(d>2.08){setState(e,'move');const s=e.kind==='wolf'?2.15:1.7;e.x+=dx/d*s*dt;e.z+=dz/d*s*dt;}else if(e.attackCd<=0){setState(e,'attack',.75);e.attackCd=e.kind==='wolf'?1.8:2.2;setTimeout(()=>{if(e.dead)return;if(Math.hypot(player.x-e.x,player.z-e.z)<2.5&&player.invuln<=0){player.hp=Math.max(0,player.hp-(e.kind==='wolf'?9:13));player.invuln=.5;setState(player,player.hp?'hit':'death',player.hp?.55:1.2);}},330);}else setState(e,'idle');}syncSprite(e);}
