function performAttack(e){if(!player.queuedAttack||player.attackCd>0)return;player.queuedAttack=false;player.energy-=20;player.attackCd=.78;setState(player,'attack',.78);setTimeout(()=>{if(e.dead)return;e.hp=Math.max(0,e.hp-24);setState(e,e.hp?'hit':'death',e.hp?.62:1.25);toast(e.hp?'24 SCHADEN':'BESIEGT',e.hp?'#fff':'#ffce66');},320);}
