function updateUI(){ui.playerHp.style.width=player.hp+'%';ui.playerEnergy.style.width=player.energy+'%';ui.playerState.textContent=player.state.toUpperCase();ui.coords.textContent=`POSITION ${player.x.toFixed(1)} / ${player.z.toFixed(1)}`;if(target&&!target.dead){const d=Math.hypot(target.x-player.x,target.z-player.z);ui.target.classList.remove('hidden');ui.targetName.textContent=target.name;ui.targetHp.style.width=target.hp/target.maxHp*100+'%';ui.targetState.textContent=target.state.toUpperCase();ui.targetHint.textContent=target.hp/target.maxHp<=.35?'FRESSBAR – E DRÜCKEN':`${Math.ceil(target.hp)} / ${target.maxHp} HP · DISTANZ ${d.toFixed(1)}`;}else ui.target.classList.add('hidden');}

canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{canvas.focus();if(e.button===2){drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId);return;}mouse.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(mouse,camera);const sprites=enemies.filter(x=>!x.dead).map(x=>x.sprite),hits=raycaster.intersectObjects(sprites,false);if(hits.length){target=hits[0].object.userData.entity;toast(target.name.toUpperCase(),'#ffda87');}else{const hit=raycaster.intersectObject(ground,false)[0];if(hit){player.combatTarget=null;player.combatDirection=null;player.combatMirror=false;player.queuedAttack=false;target=null;player.moveTarget={x:hit.point.x,z:hit.point.z};marker.position.set(hit.point.x,.04,hit.point.z);marker.visible=true;}}});
canvas.addEventListener('pointermove',e=>{if(!drag)return;yaw-=(e.clientX-lastX)*.006;pitch=THREE.MathUtils.clamp(pitch+(e.clientY-lastY)*.005,.12,1.05);lastX=e.clientX;lastY=e.clientY;});canvas.addEventListener('pointerup',e=>{if(e.button===2)drag=false;});canvas.addEventListener('wheel',e=>distance=THREE.MathUtils.clamp(distance+e.deltaY*.012,8,25),{passive:true});
document.addEventListener('keydown',e=>{keys.add(e.code);if(['KeyW','KeyA','KeyS','KeyD','Space'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Digit1')attack();if(e.code==='KeyE')eat();if(e.code==='KeyR')reset();});document.addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>keys.clear());addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight,false);});document.querySelector('#toggleHelp').onclick=()=>document.querySelector('#help').classList.toggle('hidden');

